threshold = 0.25  # Base threshold

if best_match and best_score >= threshold:
    # Calculate confidence based on score
    # Map score to confidence range:
    # 0.25 -> 0.40, 0.50 -> 0.65, 0.75 -> 0.85, 1.0+ -> 0.95
    if best_score >= 0.70:
        confidence = 0.80 + (min(best_score - 0.70, 0.30) / 0.30) * 0.15  # 0.80-0.95
