        confidence = 0.40 + ((best_score - 0.25) / 0.20) * 0.20  # 0.40-0.60

    rationale = f"Matched to '{best_match['label']}' (score: {best_score:.2f})"
    if best_match['station_match']:
        rationale += f" - station '{station}' validated"

    return (best_match['code'], best_match['label'], round(confidence, 3), rationale)
else:
    # Low match score - mark as UNKNOWN
    confidence = 0.08 + (best_score * 0.30)  # Lower confidence for unknown (0.08-0.38 range)
    rationale = f"No confident match found (best score: {best_score:.2f})"
    if best_entry:
        rationale += f" - closest: '{best_entry['standard_label']}'"

    return ("UNKNOWN", "", round(confidence, 3), rationale)

